UPDATE bottle_variants SET nose='Lemon candy, créme caramel', palate='Glazed poppyseed muffin, toasted oak', finish='Lingering wheaty finish', notes='Experimental Single Barrel 283 (May, 2024), selected by BS. Producer style: Straight Whiskey. 117.8 proof, 4 years, 4 mos. Mash: Malted Dinkel Wheat, Yellow Corn, Pale Malted Barley, Vienna Malted Barley, Munich Malted Barley. Cooperage: #2 char, + toast profile "91", 18 mo. seasoned, 53 gallon. Reserved from the same family of barrels as Experimental Batch 037: Ancient Wheat, this rare single barrel was made from an abundance of malted dinkel wheat. This heirloom wheat varietal - which dates all the way back to the dawn of civilization - contributes a nutty richness to the whiskey no longer found in modern wheat varieties. Aged in a long-seasoned, toasted & charred barrel, the result is a wildly complex and structured dram, merging notes of bright fruit, toast and baked dessert. Producer tasting note: "Lemon candy, créme caramel, glazed poppyseed muffin, toasted oak, with a lingering wheaty finish." (nose/palate/finish above are an editorial split of that line).', release_year=2024, updated_at=now() WHERE id='4990d7fb-5cc7-40b1-80db-b3e20a717e8b';

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '3bbfa0dd-fc6b-4746-8a8e-c2de5d6bd5a4', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '332', false, false, false, 124.6, '4 years, 2 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Honeyed toast, dried apricot', 'Buttered biscuit, sweet tea', 'Full bodied, warming finish', 'Experimental Single Barrel 332 (August 2025), selected by TS. Producer style: Straight Bourbon Whiskey. 124.6 proof, 4 years, 2 mos. Mash: Yellow Corn, Pale Malted White Wheat, Caramel Malted Wheat. Cooperage: #3 char, 18mo. seasoned, 53 gallon. This pot distilled wheated bourbon is made with an assertive 32% malted white wheat and 4% caramel malted wheat. Together, these two toasted and roasted specialty wheats contribute rich, sweet notes of honeyed toast, dried apricot, and sweet tea to the whiskey. Barrel 332 is the “sister” to Barrel 330, which uses malted red wheat instead of malted white wheat. Tasted side-by-side, the two barrels offer a simple but insightful look at how wheat varietal alone can shape flavor. Producer tasting note: "Honeyed toast, dried apricot, buttered biscuit, and sweet tea, with a full bodied, warming finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'ecb82160-6431-4d21-92ee-c9e5a0caa6fe', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '330', false, false, false, 123, '4 years, 2 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Graham cracker, dried cherry', 'Donut, allspice', 'Velvety, warming finish', 'Experimental Single Barrel 330 (August 2025), selected by CE. Producer style: Straight Bourbon Whiskey. 123 proof, 4 years, 2 mos. Mash: Yellow Corn, Pale Malted Red Wheat, Caramel Malted Wheat. Cooperage: #3 char, 18mo. seasoned, 53 gallon. This pot distilled wheated bourbon is made with an assertive 32% malted red wheat and 4% caramel malted wheat. Together, these two toasted and roasted specialty wheats contribute bold notes of graham cracker, dried cherry, and allspice to the whiskey. Barrel 330 is the “sister” to Barrel 332, which uses malted white wheat instead of malted red wheat. Tasted side-by-side, the two barrels offer a simple but insightful look at how wheat varietal alone can shape flavor. Producer tasting note: "Graham cracker, dried cherry, donut, and allspice, with a velvety, warming finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '5ff297c4-62c4-46ea-8f87-b6b02ba005f2', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '305', false, false, false, 125.2, '4 years, 8 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Bread pudding, fig jam, cardamom', 'Bay leaf, whipped cream', 'Toasted, malty finish', 'Experimental Single Barrel 305 (July 2025), selected by BS. Producer style: Straight Malt Whiskey. 125.2 proof, 4 years, 8 mos. Mash: Heritage Floor Malted Barley, Dehusked Pale Malted Barley, Biscuit Malted Barley, Aromatic Malted Barley, Caramel Malted Barley. Cooperage: #4 char, 18 mo. seasoning, 53 gallon. This “single malt” single barrel was crafted from a blend of roasted & toasted specialty malts—including a heritage floor malt from one of the world’s oldest and most historic malt houses in England. The barley variety, known as Maris Otter, was gently toasted over three days in a natural draft kiln, lending the malt a deep, layered complexity. Producer tasting note: "Bread pudding, fig jam, cardamom, bay leaf and whipped cream, with a toasted, malty finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'c8b03ec4-604b-4e94-9758-c7899030f90a', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '322', false, false, false, 125.3, '4 years', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Vanilla cream filling, caramel apple, buttered cinnamon toast', 'Dried fruit, with a lingering peppery spice', 'Lingering with a lingering peppery spice', 'Experimental Single Barrel 322 (June 2025), selected by BB. Producer style: Straight Bourbon Whiskey. 125.3 proof, 4 years. Mash: Yellow Corn, Malted Rye, Caramel Malted Barley, Honey Malted Barley. Cooperage: #4 char, 18 mo. seasoning, 53 gallon. Behold! This pot distilled, cask strength version of our signature “Barrel 91” recipe was aged in a barrel that was seasoned for 18 months prior to charring. By exposing the barrel staves to the outdoor elements, natural sugars in the wood are broken down more fully - which thereby increase the amount of caramelization during the barrel charring process. Charred to a level #4, expect a pronounced vanilla character reminiscent of vanilla cream filling. Producer tasting note: "Vanilla cream filling, caramel apple, buttered cinnamon toast, and dried fruit, with a lingering peppery spice." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'db7f5b44-b5e8-4b8a-aca1-a8ed63500068', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '312', false, false, false, 123.2, '4 years, 4 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Flamed orange peel, allspice, cinnamon', 'Vanilla bean, with a hint of clove, black pepper', 'Lingering black pepper', 'Experimental Single Barrel 312 (May 2025), selected by AJ. Producer style: Straight Rye Malt Whiskey. 123.2 proof, 4 years, 4 mos. Mash: Wrens Abruzzi Malted Rye (lightly smoked with apple wood), Yellow Corn, Caramel Malted Rye. Cooperage: #4 char, 18 mo. seasoning, 53 gallon. One of our most unique Experimental rye malt whiskeys to date, this pot distilled rye malt whiskey was made with a highly prized heirloom variety of rye known as Wrens Abruzzi. Known for its pronounced citrus and spice character, the grain’s punchy flavor flavor is enhanced by a very light apple wood smoking, which subtly fills out the whiskey flavor profile with additional richness, without becoming overtly smoky. Producer tasting note: "Flamed orange peel, allspice, cinnamon, and vanilla bean, with a hint of clove and black pepper." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '18a0df74-d7c6-4554-a4a6-4a5c68323b2f', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '308', false, false, false, 124, '4 years, 5 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Mixed berry compote, horchata', 'Cream soda, honey drizzled fig', 'Lingering honey drizzled fig', 'Experimental Single Barrel 308 (April 2025), selected by SR. Producer style: Straight Bourbon Whiskey. 124 proof, 4 years, 5 mos. Mash: Yellow Corn, Pale Malted Rye, Aromatic Munich Malted Barley, Caramel Aromatic Malted Barley. Cooperage: #3 char, 18 mo. seasoned, 53 gallon. Barrel 308 - the sister barrel to #306 & #307 - contains multiple varieties of "aromatic" malted barley, which undergo a warm sprouting and extended toasting process - thereby enhancing the rich, toasty aromatic qualities of the grain. By aging in a #3 char barrel that was seasoned for 18 months, this alternate version of the recipe expresses a brighter, fresh fruit character, compared to its sister barrels. Producer tasting note: "Mixed berry compote, horchata, cream soda, and honey drizzled fig." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '36049b27-8fe9-4844-90cc-01c5ac2591b5', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '307', false, false, false, 125.1, '4 years, 5 mos', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Caramel corn, snickerdoodle cookie, black tea', 'Whipped cream, fresh blackberry', 'Lingering fresh blackberry', 'Experimental Single Barrel 307 (March 2025), selected by SR. Producer style: Straight Bourbon Whiskey. 125.1 proof, 4 years, 5 mos. Mash: Yellow Corn, Pale Malted Rye, Aromatic Munich Malted Barley, Caramel Aromatic Malted Barley. Cooperage: #4 char, 18 mo. seasoned, 53 gallon. Barrel 307 - the sister barrel to Barrel 306 (and upcoming Barrel 308) - contains multiple varieties of "aromatic" malted barley, which undergo a warm sprouting and extended toasting process - thereby enhancing the rich, toasty aromatic qualities of the grain. By aging in a #4 char barrel that was seasoned for 18-mos, this alternate version of the recipe expresses a more pronounced vanilla and warm cinnamon character, compared to toasted barrel #306. Producer tasting note: "Caramel corn, snickerdoodle cookie, black tea, whipped cream, fresh blackberry." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '7c0a7735-aa5e-4c1f-a69e-63ab6365f847', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '306', false, false, false, 124, '4 years', 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Malted milk shake, dried apricot', 'Fig jam, a hint of nutmeg', 'Lingering nutmeg', 'Experimental Single Barrel 306 (January 2025), selected by JT. Producer style: Straight Bourbon Whiskey. 124 proof, 4 years. Mash: Yellow Corn, Pale Malted Rye, Aromatic Munich Malted Barley, Caramel Aromatic Malted Barley. Cooperage: #3 + toast profile "91", 53 gallon. Barrel 306 showcases an elegant & simple high malt mash bill, which contains two varieties of "aromatic" malted barley. This style of malted grain undergoes a warm sprouting and extended toasting process, which thereby enhances the rich, toasty aromatic qualities of the malt. The resulting straight bourbon whiskey showcases a warm, malty complexity reminiscent of malted milk shake. Producer tasting note: "Malted milk shake, dried apricot, fig jam, and a hint of nutmeg." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'f370aaaa-01c0-44ac-9166-4ef7c1ff0477', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '301', false, false, false, 114.6, '4 years, 2 mos', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Vanilla cream pie, toasted brioche, fresh figs', 'Dried orange peel, with a hint of black pepper', 'Lingering with a hint of black pepper', 'Experimental Single Barrel 301 (November, 2024), selected by NS. Producer style: Straight Bourbon Whiskey. 114.6 proof, 4 years, 2 mos. Mash: Yellow Corn, Pale Malted Rye, Caramel Malted Barley, Honey Malted Barley, Pale Malted Barley. Cooperage: #4 char, 53 gallon. Barrel 301 is a pot distilled variation on our signature "Barrel 91" recipe, which substitutes our typical malt whiskey yeast for a traditional bourbon yeast. The resulting bourbon experienced a faster primary fermentation, but longer secondary fermentation...therefore allowing for a more traditional bourbon flavor profile, with a subtle fruit character, balanced toward barrel expression. Producer tasting note: "Vanilla cream pie, toasted brioche, fresh figs, dried orange peel, with a hint of black pepper." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'd3e6678d-28ef-4025-8578-ad8906e0f762', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '295', false, false, false, 119, '4 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Dried cherries, plum cake, raisin bread pudding', 'Toasted oak, all spice', 'Lingering all spice', 'Experimental Single Barrel 295 (September, 2024), selected by JD. Producer style: Straight Malt Whiskey. 119 proof, 4 years. Mash: Pale Malted Barley, Floor Malted Barley, "Special B" Dark Caramel Malted Barley, Biscuit Malted Barley, Vienna Malted Barley, Caramel Malted Barley, Aromatic Malted Barley. Cooperage: #2 char, + "light" toast profile, 53 gallon. Made with nearly the same mash bill as its sister barrel, Barrel 304, this single malt whiskey also includes the addition of a unique dark caramel malt known as “Special B”. Known to brewers and distillers around the world for its rich, fruity, raisin-like character, a mere 6% of this specialty malted barley contributes more than its share of flavor and aroma. Aged in a lightly toasted and charred oak barrel for 4 years, the dried fruit-forward spirit and lightly toasty cooperage work in harmony to create this one-of-a-kind pot distilled malt whiskey. Try side-by-side with Barrel 295’s sister barrel: Barrel 304! Producer tasting note: "Dried cherries, plum cake, raisin bread pudding, toasted oak, all spice." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '2590f3c9-5dfa-4c00-8ba6-0f6a46047c3a', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '304', false, false, false, 116.8, '4 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Baklava, allspice', 'Chocolate banana bread, anise', 'Sweet, toasted biscuit finish', 'Experimental Single Barrel 304 (July, 2024), selected by AW. Producer style: Straight Malt Whiskey. 116.8 proof, 4 years. Mash: Pale Malted Barley, Floor Malted Barley, Biscuit Malted Barley, Caramel Malted Barley, Aromatic Malted Barley. Cooperage: #2 char, + "light" toast profile, 53 gallon. This unique single malt whiskey is made from 5 varieties of roasted and toasted malted barley - one of which was traditionally floor-malted in one of the world''s oldest and most historic malt houses in England. This heritage barley variety - known as Maris Otter - was gently toasted over three days in a natural draft kiln, which naturally lends a deeper flavor profile to the malt. Aged in a lightly toasted and charred oak barrel for 4 years, the malty spirit and toasty cooperage work in harmony to create this one-of-a-kind single barrel. Producer tasting note: "Baklava, allspice, chocolate banana bread, and anise with a sweet, toasted biscuit finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'b4b9a58c-fe64-4b75-98fb-5ef47590554a', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '293', false, false, false, 118.2, '4 years, 1 month', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Cherry preserves, tea biscuits, milk chocolate caramels', 'A hint of clove. Bright, malt-forward palate', 'Spiced rye finish', 'Experimental Single Barrel 293 (May, 2024), selected by TS. Producer style: Straight Bourbon Whiskey. 118.2 proof, 4 years, 1 month. Mash: Yellow Corn, Pale Malted Rye, Caramel Malted Barley (light, medium, & dark varieties). Cooperage: #4 char, 53 gallon. This Experimental Single Barrel elegantly showcases the true power of specialty malted grains. Made with our team''s go-to malted rye and a range of 3 kiln roasted caramel malts, this multi-layered mash bill was fermented with two classic yeast strains - common to both bourbon and malt whiskey. The result is a classic pot-distilled Tennessee High Malt: complex yet focused, with notes of caramel, spice, malt, and concentrated fruit. Producer tasting note: "Cherry preserves, tea biscuits, milk chocolate caramels, and a hint of clove. Bright, malt-forward palate with a spiced rye finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '8bc021ab-93a8-4cee-afb3-c2eb749992ca', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '286', false, false, false, 125.7, '4 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Notes of cinnamon bun, freshly baked rye bread', 'Raw vanilla bean, chai tea', 'Charred oak finish', 'Experimental Single Barrel 286 (April, 2024), selected by CE. Producer style: Straight Bourbon Whiskey. 125.7 proof, 4 years. Mash: Yellow Corn, Pale Malted Rye, Naked Malted Oats, Caramel Malted Barley, Smoked Malted Rye, Chocolate Malted Rye, Caramel Malted Rye. Cooperage: #4 char, 53 gallon. This Experimental Single Barrel is a blend of 3 high malt bourbons, which together contain 4 types of roasted and toasted malted rye malts. The combination of pale, smoked, chocolate, and caramel rye malt varieties results in a densely sweet & spicy flavor profile, classically associated with malted rye grain. Producer tasting note: "Notes of cinnamon bun, freshly baked rye bread, raw vanilla bean, chai tea with a charred oak finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'b4338465-179c-456a-ab7a-710283bfe113', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '192', false, false, false, 125.6, '6 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Notes of sugar cookie, nutmeg', 'Toasted almond', 'Lingering vanilla and tobacco leaf finish', 'Experimental Single Barrel 192 (April, 2024), selected by CS. Producer style: Straight Wheat Malt Whiskey. 125.6 proof, 6 years. Mash: Appalachian Malted Wheat, Yellow Corn. Cooperage: #3 char, + toast profile “47”, 53 gallon. This one-of-a-kind Experimental Single Barrel was the 1st straight wheat malt whiskey ever made at our Experimental Distillery. Made from a minimalist 2-grain mash bill - consisting of Tennessee-grown malted wheat and local stone-ground yellow corn - this under-appreciated style of whiskey proudly showcases the flavor impact of local grains, and the magic of the malting process. Producer tasting note: "Notes of sugar cookie, nutmeg, and toasted almond with a lingering vanilla and tobacco leaf finish" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '7ef3d7f9-ad48-4c4c-b30b-5fc46d9c42de', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '248', false, false, false, 128.9, '4 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Orange marmalade, cinnamon scone, caramel apple, and maple syrup', 'Notes of tobacco, toasted oak, and baking spice', 'Lingering and baking spice', 'Experimental Single Barrel 248 (March, 2024), selected by AJ. Producer style: Straight Malt Whiskey. 128.9 proof, 4 years. Mash: Pale Malted Barley, Speyside Malted Barley, Aromatic Malted Barley, Light Munich Malted Barley, Chevallier Malted Barley, Dinkel Malted Wheat, Caramel Malted Barley, Yellow Corn. Cooperage: #3 char, + toast profile “47”, 53 gallon. This one-of-a-kind straight malt whiskey utilizes multiple heritage barley varieties from both Scotland and England, prized for their depth of flavor and classic malty richness. Joined by a highly toasted "aromatic" malted barley and a small portion of dinkel malted wheat, this unconventional malt whiskey is a multi-layered, flavor-journey of a dram. Producer tasting note: "Orange marmalade, cinnamon scone, caramel apple, and maple syrup on the nose, with notes of tobacco, toasted oak, and baking spice on the palate" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '9016b08f-46da-4e1c-94e2-c7d266067820', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '277', false, false, false, 118.8, '4 years', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Dark honey, freshly baled hay', 'Caramel apple', 'Lingering caramel apple', 'Experimental Single Barrel 277 (October, 2023), selected by PH. Producer style: Straight Bourbon Whiskey. 118.8 proof, 4 years. Mash: Yellow Corn, Malted Rye, Caramel Malted Barley, Honey Malted Barley. Cooperage: #3 char, 18 month seasoned, 53 gallon. This pot distilled version of our signature "Barrel 91" recipe was aged in a cask that was seasoned for 18 months prior to its charring. By exposing the barrel staves to the outdoor elements, natural sugars in the wood are broken down more fully, and thereby increase the amount of caramelization during the barrel charring process. Producer tasting note: "Dark honey, freshly baled hay, and caramel apple" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '08c0e884-1025-4465-a2a2-f28168564723', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '240', false, false, false, 124.5, '4 years, 5 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Caramel apple, rum raisin ice cream, zucchini bread', 'Baklava, dried apricot', 'Lingering dried apricot', 'Experimental Single Barrel 240 (August, 2023), selected by GM. Producer style: Straight Bourbon Whiskey. 124.5 proof, 4 years, 5 mos. Mash: Yellow Corn, Pale Malted Barley, Honey Malted Barley, Caramel Malted Rye, Dark "Munich" Malted Barley. Cooperage: #3 char + "Light" toast profile, 53 gallon. Aged in a barrel that was lightly toasted prior to charring, this high malt bourbon includes a variety of lightly toasted & caramelized rye and barley malts. Together, the toasted barrel and grains add synergized flavors reminiscent of baking spice, dark fruit and sweet breads. Producer tasting note: "Caramel apple, rum raisin ice cream, zucchini bread, baklava and dried apricot" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'c438376b-6f3d-4371-8ab9-555da59e2237', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '247', false, false, false, 120.3, '4 years', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Caramel, coffee cake', 'Butterscotch, cocoa, and light black pepper', 'Lingering and light black pepper', 'Experimental Single Barrel 247 (July, 2023), selected by NS. Producer style: Straight Bourbon Whiskey. 120.3 proof, 4 years. Mash: Yellow Corn, Pale Malted Barley, CaraMunich Malted Barley, Honey Malted Barley, Aromatic Malted Barley, Caramel Malted Rye, Chocolate Malted Barley, Malted Oats. Cooperage: #3 char + toast, 53 gallon. Bursting with rich, dessert-like flavors, this single barrel owes its layered complexity to the multiple varieties of toasted and roasted barley, rye and oat malts. Discover the contribution of each specialty malt by adding a small amount of water in between each sip of whiskey! Producer tasting note: "Caramel, coffee cake on the nose. Butterscotch, cocoa, and light black pepper on the palate" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '230ed726-92de-4483-8226-a493e0c357b1', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '96', false, false, false, 132.8, '5 years', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Earthy smoke, ripe fruit', 'Toasted granola', 'Lingering toasted granola', 'Experimental Single Barrel 96 (June, 2023), selected by SR. Producer style: Straight Bourbon Whiskey. 132.8 proof, 5 years. Mash: Yellow Corn, Peat Smoked Malted Barley, Malted Naked Oats, Honey Malted Barley, Caramel Malted Barley, Malted Rye. Cooperage: #3 char + toast, 53 gallon. Inspired by the rich world of Islay Scotch, this high malt "peated" bourbon was made with a heavy hand of peat smoked malted barley, "naked" malted oats and honey malted barley. Producer tasting note: "Earthy smoke, ripe fruit, and toasted granola" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'd2c602b1-1b2b-43b7-8b81-b568662df96a', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '204', false, false, false, 120.3, '4 years', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Lightly floral', 'Lightly floral', 'Notes of white grape, grapefruit brûlée, meringue and tobacco leaf. Warming, full bodied finish with a touch of clove', 'Experimental Single Barrel 204 (April, 2023), selected by LZ. Producer style: Straight Malt Whiskey. 120.3 proof, 4 years. Mash: Five varieties of Pale Malted Barley, Aromatic Malted Barley, Light Munich Malted Barley, Pale Malted Rye. Cooperage: #3 char, + toast profile “47”, 53 gallon. This unique single barrel – known to our distillers as a “catch single barrel” – contains malt whiskey from multiple recipes and distillation runs. Over the course of 10 months, each recipe''s distillate topped up the barrel and reset the age. Once completely full, the whiskey was aged for over 4 years in a heavily toasted and charred barrel, before bottling. Producer tasting note: "Lightly floral with notes of white grape, grapefruit brûlée, meringue and tobacco leaf. Warming, full bodied finish with a touch of clove." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '955e757c-1e2e-4589-81f6-3dbc450a012c', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '172', false, false, false, 125, '5 years, 7 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Honey baked ham, sticky toffee pudding', 'Date jam, charred oak', 'Full bodied & sweet-smoky finish', 'Experimental Single Barrel 172 (April, 2023), selected by JT. Producer style: Straight Bourbon Whiskey. 125 proof, 5 years, 7 mos. Mash: Yellow Corn, Cob Smoked Malted Barley, Appalachian Malted Wheat. Cooperage: #4 char, 53 gallon. This one-of-a-kind single barrel was made with 18% corn cob-smoked malted barley, made for us by Valley Malt (Holyoke, MA) using cobs from our distillery''s corn! Producer tasting note: "Honey baked ham, sticky toffee pudding, date jam and charred oak, with a full bodied & sweet-smoky finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '7e2d590c-4bff-4640-b6c3-680607f4000b', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '202', false, false, false, 120.8, '4 years', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Chantilly cream, toasted hazelnut, cinnamon toast', 'Vanilla bean, rum cake', 'Lingering rum cake', 'Experimental Single Barrel 202 (March, 2023), selected by AW. Producer style: Straight Bourbon Whiskey. 120.8 proof, 4 years. Mash: Yellow Corn, White Corn, Pale Malted Barley, Flaked Barley, Malted Rye, Caramel Malted Barley, Honey Malted Barley. Cooperage: #3 char, + toast profile “47”, 53 gallon. This unique single barrel – known to our distillers as a “catch single barrel” – contains bourbon whiskey from multiple recipes and distillation runs. Over the course of 8 months, each recipe''s distillate topped up the barrel and reset the age. Once completely full, the whiskey was aged for over 4 years in a heavily toasted and charred barrel. Producer tasting note: "Chantilly cream, toasted hazelnut, cinnamon toast, vanilla bean, rum cake" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '3c2707ab-8ad9-48fe-9757-c9120d923a73', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '206', false, false, false, 122.6, '4 years, 7 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Briny smoke, honey & oats', 'Shortbread cookie, bread pudding', 'Lingering bread pudding', 'Experimental Single Barrel 206 (February, 2023), selected by CC. Producer style: Straight Bourbon Whiskey. 122.6 proof, 4 years, 7 mos. Mash: Yellow Corn, Simpsons Peated Malted Barley, Honey Malted Barley, Malted Rye. Cooperage: #3 char, + toast profile “47”, 53 gallon. This peated bourbon was made with peat smoked malt made by Simpsons Malt in Northumberland, UK. This single barrel, and its sister barrel, #213 have identical mash bills - except for their peated malts - which were malted and smoked by a different maltster. Producer tasting note: "Briny smoke, honey & oats, shortbread cookie and bread pudding." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '76975fff-87d5-43c2-834f-639d772d8788', 'fdce97fc-50dc-48cc-85b3-bc6e98f04ad0', '213', false, false, false, 124.7, '4 years, 6 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e851f395-f309-4e49-85de-a5f8fd2c2779/front.webp', 290, 'estimated',
  true, now(), 'Producer stock image for the Experimental Single Barrel line (label shows Barrel #172; Chattanooga publishes no number-free shot).',
  'Sweet earthy smoke, toffee pudding', 'Apple crisp, caramel candy', 'Lingering caramel candy', 'Experimental Single Barrel 213 (February, 2023), selected by BS. Producer style: Straight Bourbon Whiskey. 124.7 proof, 4 years, 6 mos. Mash: Yellow Corn, Thomas Fawcett Peated Malted Barley, Honey Malted Barley, Malted Rye. Cooperage: #3 char, + toast profile “47”, 53 gallon. This peated bourbon was made with peat smoked malt made by Simpsons Malt in Northumberland, UK. This single barrel, and its sister barrel, #206 have identical mash bills - except for their peated malts - which were malted and smoked by a different maltster. Producer tasting note: "Sweet earthy smoke, toffee pudding, apple crisp and caramel candy." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '96a64b16-233e-4263-a9c8-5c2ed1613442', 'd9cffc22-e158-44b9-8df5-c208403cf512', 'Alpha-1', false, false, false, 84, NULL, NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/96a64b16-233e-4263-a9c8-5c2ed1613442/shelf-mtxapeq2-qjwg.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Like having your brains smashed in by a bag of lemons dipped in 42 karat gold', 'Like having your brains smashed in by a bag of lemons dipped in 42 karat gold', 'Golden (producer: "dipped in 42 karat gold")', 'Experimental Batch Alpha-1. Mash Bill: Classified. Proof: 84 (42% Alc/Vol). Infused with: At least 42 botanicals. Intensity: 6EQUJ5. Recipe Coords: 1698/1009. Batch Size: 12 barrels. Style: Bourbon Liqueur. It’s a dark time at Chattanooga Whiskey. A year ago, Intergalactic Comet Crusher practically saved the world, but nobody even cared. Instead of having a parade, everyone now demanded full-frontal recipe disclosure—no redactions! To distract from the cover-up, the distillers escaped aboard their UFO, and went back to the future to make another batch of Comet Crusher. But then, [REDACTED] forgot the original recipe in their other pants, which cross-contaminated the timeline and nearly destroyed the universe. Don’t panic—everything’s pretty much fine now. Aaanyways… as an apology for the mess, please accept this time-altered sequel. We hope it smashes your brains even harder than the original. Observables (per SA797): V, V1 Producer tasting note: "Like having your brains smashed in by a bag of lemons dipped in 42 karat gold" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '6429df76-1e14-45cd-987d-c2ec8f1d985e', 'd9cffc22-e158-44b9-8df5-c208403cf512', '048: Strawberry Infused Gin Liqueur', false, false, false, 85, NULL, 2026, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/6429df76-1e14-45cd-987d-c2ec8f1d985e/shelf-mtxapfek-senc.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Balsamic drizzled strawberries, bubblegum, cardamom biscotti', 'Juniper berry, lemon zest', 'Lingering lemon zest', 'Experimental Batch 048: Strawberry Infused Gin Liqueur (May 7 2026). Mash Bill: Yellow Corn, Rye Malt, “Pink Boots” Barley Malt. Distilled with: Juniper, Coriander, Lemon Peel, Cardamom, Ginger, Vanilla, Szechuan Peppercorn. Infused with: Strawberries, Rhubarb, Raspberries, Lemon Peel, Eucalyptus Leaf. Proof: 85 (42.5% Alc/Vol). Still Type: Continuous Column. Batch Size: ~3,000 bottles. Style: Gin Liqueur. Release Date: May 7 2026. Producer tasting note: "Balsamic drizzled strawberries, bubblegum, cardamom biscotti, juniper berry, and lemon zest" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'a4104d67-5492-48e6-9373-d167aec5f99a', 'd9cffc22-e158-44b9-8df5-c208403cf512', '047: Single Pot Still', false, false, false, 95, NULL, 2026, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/a4104d67-5492-48e6-9373-d167aec5f99a/shelf-mtxapfxi-1abp.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Toasted granola, baked pear', 'Gingersnap cookie, vanilla icing', 'Long, creamy finish', 'Experimental Batch 047: Single Pot Still (February 5 2026). Mash Bill: Floor Malted Barley, Calypso Unmalted Barley, Pale Malted Barley, Hulless Malted Oats. Proof: 95 (47.5% Alc/Vol). Distillation: 2 times. Still Type: 100 gal pot still. Cooperage: Toasted & Charred Oak Barrels, 53 gallon. Batch Size: 5 barrels. Style: Straight Malt Whiskey. Release Date: February 5 2026. Producer tasting note: "Toasted granola, baked pear, gingersnap cookie, vanilla icing, with a long, creamy finish" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '31c63e31-1e1f-4464-83f2-b2752e5dfe3c', 'd9cffc22-e158-44b9-8df5-c208403cf512', '046: Spiced Cacao Infused', false, false, false, 85, NULL, 2025, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/31c63e31-1e1f-4464-83f2-b2752e5dfe3c/shelf-mtxapghb-buvy.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Dark chocolate, prune, toasted chile pepper', 'Chocolate covered raisin, horchata', 'Lingering horchata', 'Experimental Batch 046: Spiced Cacao Infused (November 20 2025). Mash Bill: A blend of 3 high malt bourbon mash bills. Grains: Yellow Corn, Pale Malted Rye, Honey Malted Barley, Caramel Malted Barley, Pale Malted Wheat, Caramel Malted Wheat, Acidulated Malted Rye, Chocolate Malted Rye. Proof: 85 (42.5% Alc/Vol). Infused with: Cacao Nibs (Ecuadorian), Guajillo & Pasilla Chiles, Cinnamon, Vanilla Beans. Distillation: Double Pot & Continuous Column. Cooperage: Toasted & Charred Oak Barrels. Batch Size: 7 barrels. Style: Bourbon Liqueur. Release Date: November 20 2025. Producer tasting note: "Dark chocolate, prune, toasted chile pepper, chocolate covered raisin, horchata" (nose/palate/finish above are an editorial split of that line).', now(), now());

