  '16542a86-ba71-469b-90c8-06ff64c010b4', 'd9cffc22-e158-44b9-8df5-c208403cf512', '044: Bourbon Barreled Limecello', false, false, false, 83.2, NULL, NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/16542a86-ba71-469b-90c8-06ff64c010b4/shelf-mtxaphjl-jw6q.webp', 290, 'estimated',
