  '96bfd775-a176-4b5f-93a0-f1f5920cd10b', 'd9cffc22-e158-44b9-8df5-c208403cf512', '039: Harvest Bourbon', false, false, false, 115, '5 years', 2024, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/96bfd775-a176-4b5f-93a0-f1f5920cd10b/shelf-mtxapkpj-twnh.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Snickerdoodle cookie, fruit cake, oatmeal creme pie', 'Horchata, rice pudding', 'Lingering rice pudding', 'Experimental Batch 039: Harvest Bourbon (August 2024). Mash Bill: 60% Yellow Corn, 10% Malted Triticale, 9% Malted Rice, 9% Malted Oats, 7% Jasmine Rice, 3% Malted Barley, 2% Malted Rye. Distillation: Double Pot. Age: 5 years. Proof: 115 (57.5 Alc/Vol). Batch Size: 6 barrels. Style: Straight Bourbon Whiskey. Release Date: August 2024. Cooperage: #3 char, 18 mo. seasoned (33%), #3 char + toast profile “91” (33%), #1 char + toast profile “91”, 18 mo. seasoned (33%), all 53 gallon Producer tasting note: "Snickerdoodle cookie, fruit cake, oatmeal creme pie, horchata, and rice pudding" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
