  'Walnut raisin bread, dried apricot, brown sugar', 'Nutmeg, molasses, sweet tea', 'Lingering sweet tea', 'Experimental Batch 037: Ancient Wheat. Age of Blend: 4 years. Proof: 105 (52.5% Alc/Vol). Cooperage: Toasted & Charred Oak, 53 gallon (3 types). Batch Size: 3 barrels. Style: A blend of straight whiskeys. Mash Bill/Style 2: Straight Wheat Malt Whiskey (33%) Producer tasting note: "Walnut raisin bread, dried apricot, brown sugar, nutmeg, molasses, and sweet tea" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '5bde3a5b-55be-4185-8eb9-2fc02a0b0ba2', 'd9cffc22-e158-44b9-8df5-c208403cf512', '036: Herbal Infused', false, false, false, 81, NULL, NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/5bde3a5b-55be-4185-8eb9-2fc02a0b0ba2/shelf-mtxapmde-upso.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Root beer float, black licorice', 'Blueberry preserves', 'Lingering blueberry preserves', 'Experimental Batch 036: Herbal Infused. Proof: 81 (40.5% Alc/Vol). Distillation: Double Pot & Continuous Column. Batch Size: 4 Barrels. Infused With: Anise Seed Pods, American Ginseng, Indian Sarsaparilla, Bilberry, Sour Cherry, Ginger, Vanilla Bean, Anise-Hyssop, Linden, Caraway Seeds, Horehound, Centaury, Spearmint, Burdock Root. Style: Bourbon Liqueur/Kräuterlikör. Age of Whiskey (Pre Infusion): 40% 5 Years, 60% less than 24 Hours Finishing Time (Post Infusion): 1 Year Cooperage (Pre Infusion): Charred Oak, Single-Use Bourbon Barrels, 53 gal Finishing Cooperage (Post Infusion): Single-Use Bourbon Barrels chocolate mint, with a woody ginseng finish Producer tasting note: "Root beer float, black licorice, blueberry preserves," (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '7067896d-8dae-4669-8095-0aec09d81269', 'd9cffc22-e158-44b9-8df5-c208403cf512', '035: Centenary Cask', false, false, false, 100, 'Greater than 4 years', NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/7067896d-8dae-4669-8095-0aec09d81269/shelf-mtxapmxa-b27y.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Delicate aged notes of fruit cake, black tea', 'Cigar box, bread crust', 'Lightly mineral Oloroso finish', 'Experimental Batch XXXV: Centenary Cask. Age: Greater than 4 years. Proof: 100 (50% ALC/VOL). Cooperage: Toasted & Charred Oak, 53 gallon. Finishing Cooperage: Centenary Oloroso Sherry Puncheon (c. 1915). Finishing Time: 12 mos. Barrel Blend: 267, 275. Style: Straight Bourbon Whiskey finished in an Oloroso Sherry Cask. Fill No.: 3 Mash Bills: Barrel 267: Yellow Corn, Pale Malted Rye, Pale Malted Wheat, Honey Malted Barley, Caramel Malted Barley, Caramel Malted Rye, Chocolate Malted Rye Producer tasting note: "Delicate aged notes of fruit cake, black tea, cigar box and bread crust, with a lightly mineral Oloroso finish" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '88e8fa45-b801-4e64-8ca0-49eb62395f59', 'd9cffc22-e158-44b9-8df5-c208403cf512', '034: Pecan Infused', false, false, false, 84, NULL, 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/88e8fa45-b801-4e64-8ca0-49eb62395f59/shelf-mtxapngz-ssjz.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Turtle chocolate, toasted coconut', 'Praline, sweet potato pie', 'Lingering sweet potato pie', 'Experimental Batch 034: Pecan Infused (November, 2023). Grains: Corn, Malted Corn, Malted Barley, Smoked Malted Barley, Malted Rye, Malted Wheat, Malted Triticale, Rice. Proof: 84 (42% ALC/VOL). Infused with: Roasted Pecans, Vanilla Beans, Cacao Nibs, Coconut, Orange Peel, Dark Candi Syrup. Distillation: Double Pot. Cooperage: Toasted & Charred Oak, 53 gallon. Batch size: 7 barrels. Style: Bourbon Liqueur. Release Date: November, 2023. Producer tasting note: "Turtle chocolate, toasted coconut, praline, and sweet potato pie" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '366d6f2e-219d-4ccb-b7ba-f8ca96ba5918', 'd9cffc22-e158-44b9-8df5-c208403cf512', '033: Triple Peat', false, false, false, 111, '4 years, 2 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/366d6f2e-219d-4ccb-b7ba-f8ca96ba5918/shelf-mtxapo1q-30ya.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Smoked apple, heather honey', 'Caramel sauce & raisin scone', 'Lingering, peaty finish', 'Experimental Batch 033: Triple Peat (September, 2023). Grains: Yellow Corn, Peat Smoked Malted Barley (3 types), Honey Malted Barley, Naked Malted Oats, Malted Rye. Age: 4 years, 2 mos. Proof: 111 (55.5% ALC/VOL). Cooperage: Toasted & Charred Oak, 53 gallon. Finishing Cooperage: Islay Scotch Barrels (blend of 3 types), 250 liter. Finishing Time: 9-24 months. Batch Size: 8 barrels. Style: Blend of Straight Whiskeys finished in Islay Scotch Barrels. Release date: September, 2023. 3 peated whiskeys, 3 peated malts, 3 peated finishing casks. Can you handle the peat? This blend of pot distilled bourbon, column distilled bourbon and column distilled malt whiskey was made with 3 different peated malts from 3 different UK malthouses - each one bringing their own unique, rich, smoky malt character. Producer tasting note: "Smoked apple, heather honey, caramel sauce & raisin scone, with a lingering, peaty finish" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'e45c92b3-f74a-409a-848e-ae0dc92564e1', 'd9cffc22-e158-44b9-8df5-c208403cf512', '032: Bourbon Barreled Limoncello', false, false, false, 86, NULL, 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/e45c92b3-f74a-409a-848e-ae0dc92564e1/shelf-mtxapol8-x7gw.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Lemon curd, panettone', 'Shortbread & creamsicle', 'Lingering shortbread & creamsicle', 'Experimental Batch 032: Bourbon Barreled Limoncello (September, 2023). Proof: 86 (43% ALC/VOL). Infused with: Lemon Peel, Orange Peel, Vanilla Bean. Distillation: Double Pot & Continuous Column. Finishing Cooperage: Single-use Tennessee High Malt, 53 gallon. Finishing Time: 3 mos. Batch size: 3 barrels. Style: Liqueur. Release Date: September, 2023. Inspired by the Italian flavor combination known as "fiori di sicilia", our version of this iconic liqueur was infused with an abundance of meyer lemon peel, orange peel & vanilla bean before being finished in single-use toasted & charred barrels for over 3 months. Made with our signature "Barrel 91" mash bill - and over 100 pounds of lemon peel - our fruity & floral white whiskey served as the perfect base for a lengthy 2-week infusion of citrus and vanilla. Crafted from only real ingredients, this simple yet elegant liqueur showcases the refreshing summertime flavors of an Italian classic, alongside our very own Tennessee High Malt. Producer tasting note: "Lemon curd, panettone, shortbread & creamsicle" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '1841fbbb-4889-45aa-b8d6-19367d56f034', 'd9cffc22-e158-44b9-8df5-c208403cf512', '031: Red, White & Blue Grist', false, false, false, 102, '4 years, 2 mos', 2023, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/1841fbbb-4889-45aa-b8d6-19367d56f034/shelf-mtxapp60-mpld.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Dried fig, sweet corn cake', 'Berries & cream, almond croissant', 'Lingering almond croissant', 'Experimental Batch 031: Red, White & Blue Grist (May, 2023). Age: 4 years, 2 mos. Proof: 102 (51% ALC/VOL). Cooperage: #3 char, + toast profile “47”, 53 gallon. Batch Size: 6 barrels. Style: Straight Bourbon Whiskey. Release Date: May, 2023. Made with red, white & blue corn varieties, this Experimental Single Batch commemorates the 10th anniversary of Tennessee''s "Whiskey Bill", which legalized spirits production in Chattanooga, Tennessee for the first time in over 100 years. Formally known as State House Bill 102, this important legislation ushered in dozens of new distilleries across the entire state of Tennessee, and is now an enduring symbol of community-powered change. Producer tasting note: "Dried fig, sweet corn cake, berries & cream, almond croissant" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'ba3a3f99-f2e4-4801-9c1f-c168cfb690b3', 'd9cffc22-e158-44b9-8df5-c208403cf512', '029: Centenary Cask', false, false, false, 100, 'Greater than 4 years', NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/ba3a3f99-f2e4-4801-9c1f-c168cfb690b3/shelf-mtxappr8-bb66.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Aged-wine aromas of soaked fruit cake, toasted walnut', 'Bread pudding', 'Lingering bread pudding', 'Experimental Batch XXIX: Centenary Cask. Age: Greater than 4 years. Proof: 100 (50% ALC/VOL). Cooperage: Toasted & Charred Oak, 53 & 25 gallon. Finishing Cooperage: Centenary Oloroso Sherry Puncheon (c. 1915). Finishing Time: 12 mos. Barrel Blend: 001, 168, 180, 187. Batch Size: 100 proof gallons. Style: Straight Bourbon Whiskey finished in an Oloroso Sherry Cask. Fill No. 2 Mash Bills: Barrel 001: Yellow Corn, Unmalted Rye, Pale Malted Barley Barrel 180: Yellow Corn, Pale Malted Wheat, "Melanoidin" Malted Barley, Carafa Malted Barley Barrel 187: Yellow Corn, Malted Wheat, Munich Malted Barley, Kiln Coffee Malted Barley, "Black Pearl" Malted Barely Producer tasting note: "Aged-wine aromas of soaked fruit cake, toasted walnut and bread pudding" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  'fa096ccc-00d7-409d-892c-1f6c9d5a8297', 'd9cffc22-e158-44b9-8df5-c208403cf512', '028: Cacao Infused', false, false, false, 86, '4 years, 9 mos', NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/fa096ccc-00d7-409d-892c-1f6c9d5a8297/shelf-mtxapqcc-yxqp.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Mexican Hot Chocolate, Toasted Coconut', 'Dark Caramel & Snickerdoodle Cookie', 'Lingering Dark Caramel & Snickerdoodle Cookie', 'Experimental Batch 028: Cacao Infused. Age of Bourbon: 4 years, 9 mos. Proof: 86 (43% ALC/VOL). Infused with: Roasted Cacao Nibs, Vanilla Beans, Cassia Cinnamon Sticks. Cacao Origin: Tanzania, Peru (blend). Cooperage: Toasted & Charred Oak, 53 gallon. Batch Size: 4 barrels. Style: Bourbon Liqueur. Inspired by the wintertime flavors of Mexican hot chocolate, this high malt bourbon liqueur was built from an experimental mash containing a unique blend of roasted malts. The whiskey was then infused with a variety of ingredients, including two types of cacao nibs - each roasted to highlight characteristics from their respective terroirs. The result celebrates the chocolatey flavors from both whiskey and cacao. Enjoy chilled, on ice, at dessert, on dessert... or as dessert! Dessert! Producer tasting note: "Mexican Hot Chocolate, Toasted Coconut, Dark Caramel & Snickerdoodle Cookie" (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '16811dbb-4cfe-40b7-b48d-f12d33af5ea1', 'd9cffc22-e158-44b9-8df5-c208403cf512', '027: Moscatel + Sauternes Barrel Finished', false, false, false, 110, '4 years', 2022, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/16811dbb-4cfe-40b7-b48d-f12d33af5ea1/shelf-mtxapqx9-azxt.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'White raisin, coriander', 'Saffron & hard pretzel', 'Floral, grassy finish', 'Experimental Batch 027: Moscatel + Sauternes Barrel Finished (October, 2022). Age: 4 years. Proof: 110 (55% ALC/VOL). Cooperage: Toasted & Charred Oak, 53 gallon. Finishing Cooperage: Moscatel de Setúbal & Sauternes Barrels, 225 liter. Finishing Time: 19-24 months. Batch Size: 7 barrels. Style: Straight Bourbon Whiskey finished in Moscatel and Sauternes Barrels. Release Date: October, 2022. Producer tasting note: "White raisin, coriander, saffron & hard pretzel, with a floral, grassy finish." (nose/palate/finish above are an editorial split of that line).', now(), now());

INSERT INTO bottle_variants (id, bottles_id, batch, is_default, is_catchall, verified, proof, age, release_year, frontimage_url, bottle_height, bottle_height_source, shelf_ready, image_reviewed_at, image_review_note, nose, palate, finish, notes, created_at, updated_at) VALUES (
  '508be75d-7007-4f4c-af8f-3d7ed9773d55', 'd9cffc22-e158-44b9-8df5-c208403cf512', '026: Bourbon Barreled Gin', false, false, false, 102, NULL, NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/508be75d-7007-4f4c-af8f-3d7ed9773d55/shelf-mtxapri7-utmt.webp', 290, 'estimated',
  false, NULL, 'Producer bottle shot, cut out by scripts/chattanooga_load.mjs; needs a look on a real shelf.',
  'Wildflower honey, hibiscus', 'Strawberry lemonade, juniper', 'Lingering juniper', 'Experimental Batch 026: Bourbon Barreled Gin. Botanicals: Honey, Juniper, Hibiscus, Coriander, Honey Malt, Szechuan Peppercorn, Orris Root, Orange Peel, Lemon Peel, Angelica Root. Proof: 102 (51% ALC/VOL). Finishing Cooperage: Single-Use Tennessee High Malt, 53 gallon. Finishing Time: 6 mos. Batch Size: 4 barrels. Style: "Old Tom” Gin. High Malt gin, take 2. Crafted from a variety of botanicals including honey, hibiscus, coriander & juniper, our second Experimental gin explores the sweeter, fruitier style of gin, known as “Old Tom." Made from a base of our signature Tennessee High Malt mash bill, this gin was infused & distilled with a blend of 10 botanicals before being finished in single use bourbon barrels for over 6 months. The result is a fruit-forward, whiskey lover’s gin - perfectly suited for a Tom Collins cocktail! Producer tasting note: "Wildflower honey, hibiscus, strawberry lemonade, and juniper." (nose/palate/finish above are an editorial split of that line).', now(), now());

