  '6c444b10-3cc4-4dc1-a8fd-03378c6fddc9', 'd9cffc22-e158-44b9-8df5-c208403cf512', '025: Appalachian Grist', false, false, false, 102, '4 years', NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/6c444b10-3cc4-4dc1-a8fd-03378c6fddc9/shelf-mtxaps34-g9qr.webp', 290, 'estimated',
