  'b2e74d9d-3530-44fd-90f2-68f6849fa995', 'd9cffc22-e158-44b9-8df5-c208403cf512', '021: Vatted High Malt', false, false, false, 100, '4 years, 1 month', NULL, 'https://bicpipgbspasxbtqjzvg.supabase.co/storage/v1/object/public/bottle-images/variants/b2e74d9d-3530-44fd-90f2-68f6849fa995/shelf-mtxapuvh-izfy.webp', 290, 'estimated',
